from ta_messaging.exceptions import MessageVerifierAlreadyExists
from ta_messaging.exceptions import WrongQuerySyntax
from ute_common_abstract_core.message_query_builder import message_query_parser
import logging
import re

known_compare_operators = ['eq', 'ne', 'lt', '<', 'le', 'gt', '>', 'ge']
known_presence_operators = ['is present', 'is not present']
verifiers = {}


def message_verifier(func):
    '''
    Decorator for user-defined function (func) that is used to verify message contents in MessageObserver thread.

    To use import this verifier and use it as decorator to your function .e.g::

        @message_verifier
        def test_sth_on_message(msg):
        ... return True

    Then when declaring the message flow the same name should be used in () brackets e.g.::

        Expect Message Flow
        ...                  TEST_UE_1:RRC_rrcConnectionReconfiguration (Test sth on Message)
        ...                  TEST_UE_1:RRC_rrcConnectionReconfigurationComplete as rrc_complete
        ...                  alias=ATTACH_FLOW  overall_timeout=10

    :param func: function to decorate
    :return: decorated user-defined func
    '''
    def wrapped_verifier(*args, **kwargs):
        '''
        Function wrapping the execution of user_defined callback. If catches error and non-boolean returns and
        changes them to False. A valid verifier should only return True or False.

        :param args:
        :param kwargs:
        :return: boolean
        '''
        logger = logging.getLogger('messaging.flows.logic')
        try:
            result = func(*args, **kwargs)
            if isinstance(result, bool):
                return result
            else:
                raise Exception('Message verifier returned: {} instead of [True, False]'.format(result))
        except Exception as error:
            err_name = error.__class__.__name__
            logger.warning("User defined message verifier: {}() failed to execute with {} error: {}"
                           .format(func.__name__, err_name, error))
            return False
    wrapped_verifier.__wrapped__ = func
    _normalized_name = str(func.__name__).lower()
    if _normalized_name not in verifiers:
        verifiers[_normalized_name] = wrapped_verifier
    else:
        raise MessageVerifierAlreadyExists(_normalized_name)
    return wrapped_verifier


def get_registered_verifiers():
    '''
    :return: dict with names or registered verifiers as keys
    '''
    return verifiers


def _split_field_simple_query_description(description):
    """
    Split field and query description to parts

    :param description: looks like   measParameters-v1020..interFreqBandList is present
    :return: field_description, operator, value
    """
    field_description, operator, value = description.split(" ", 2)
    if (operator.lower() == 'is') and ('present' in value.lower()):
        operator += ' ' + value
        value = ''
        _validate_presence_operator(description, operator)
    else:
        _validate_compare_operator(description, operator)
    return field_description, operator.lower(), value


def _validate_presence_operator(description, operator):
    if operator.lower() not in known_presence_operators:
        err_msg = "'{}' - invalid '{}' operator; allowed presence operators: '{}'".format(description, operator,
                                                                                          "' '".join(known_presence_operators))
        raise WrongQuerySyntax(err_msg)


def _validate_compare_operator(description, operator):
    if operator.lower() not in known_compare_operators:
        err_msg = "'{}' - invalid {} operator; allowed comparison operators: {}".format(description, operator,
                                                                                        " ".join(
                                                                                            known_compare_operators))
        raise WrongQuerySyntax(err_msg)


def _split_field_description(description):
    """
    Split field description to parent-fields list

    :param description: looks like   ueCapabilityInformation-r8..measParameters-v1020..interFreqBandList
    :return: field path list
    """
    if '.' not in description:
        return [description]
    _validate_parent_field_separators(description)

    field_path = re.split(r'\.+', description)
    assert '.' not in field_path[0]
    assert '.' not in field_path[-1]

    return field_path


def _validate_parent_field_separators(description):
    """Validate if all separators are '..' """
    if description.startswith('..') or description.endswith('..'):
        err_msg = "'{}' - parent field separator '..' may be used only between field names".format(description)
        raise WrongQuerySyntax(err_msg)

    wrong_separators = []
    for separator in re.findall(r'\.+', description):
        if separator != '..':
            wrong_separators.append("'{}'".format(separator))
    if wrong_separators:
        err_msg = "'{}' - invalid {} parent field separator; should be '..'".format(description,
                                                                                    " ".join(wrong_separators))
        raise WrongQuerySyntax(err_msg)


def _build_query_from_field_simple_query_description(description):
    """
    Generate messaging query string for field and query description

    :param description: looks like   ueCapabilityInformation-r8..measParameters-v1020..interFreqBandList is present
    :return: messaging query string
    """
    field_description, operator, value = _split_field_simple_query_description(description)
    field_path = _split_field_description(field_description)
    if "present" in operator:  # unary operator
        inner_query = "{} {}".format(field_path[-1], operator)
    else:
        inner_query = "{} {} {}".format(field_path[-1], operator, value)
    query = inner_query
    if len(field_path) > 1:
        for parent_field in field_path[-2::-1]:
            query = "{} contains ({})".format(parent_field, query)
    return query


def _build_full_query_from_field_query_descriptions(descriptions):
    queries = []
    for field_query_description in descriptions:
        single_field_query = _build_query_from_field_simple_query_description(field_query_description)
        queries.append(single_field_query)
    if len(queries) > 1:
        query = "({})".format(") and (".join(queries))
    else:
        query = queries[0]
    return query


def build_message_verifier_from_field_query_descriptions(descriptions):
    full_query = _build_full_query_from_field_query_descriptions(descriptions)
    query_parsed_verifier = message_query_parser().parse(input=full_query)['action_result']
    return query_parsed_verifier


def build_message_verifier_from_query(query_parts):
    full_query = " ".join(query_parts)
    query_parsed_verifier = message_query_parser().parse(input=full_query)['action_result']
    return query_parsed_verifier
